<main class="wrap">
  <h1>Cooking Unit Converter</h1>
  <p class="sub">Type a number to convert between metric and US kitchen units. Conversions update as you type.</p>

  <section class="card" aria-labelledby="wt-h">
    <h2 id="wt-h">Weight</h2>
    <div class="grid" style="margin-top:14px">
      <div class="field">
        <label for="wt-from">From</label>
        <input id="wt-from" type="number" inputmode="decimal" step="any" value="100" aria-describedby="wt-hint">
      </div>
      <div class="field">
        <label for="wt-fromu">Unit</label>
        <select id="wt-fromu"></select>
      </div>
    </div>
    <div class="eq"><span class="line"></span><span class="tag">equals</span><span class="line"></span></div>
    <div class="result" id="wt-result">—</div>
    <div class="hint" id="wt-hint"></div>
    <div class="chips" id="wt-chips"></div>
    <p class="note">Volume results use the ingredient density you pick below.</p>
  </section>

  <section class="card" aria-labelledby="vol-h">
    <h2 id="vol-h">Volume</h2>
    <div class="grid" style="margin-top:14px">
      <div class="field">
        <label for="vol-from">From</label>
        <input id="vol-from" type="number" inputmode="decimal" step="any" value="250" aria-describedby="vol-hint">
      </div>
      <div class="field">
        <label for="vol-fromu">Unit</label>
        <select id="vol-fromu"></select>
      </div>
    </div>
    <div class="eq"><span class="line"></span><span class="tag">equals</span><span class="line"></span></div>
    <div class="result" id="vol-result">—</div>
    <div class="hint" id="vol-hint"></div>
    <div class="chips" id="vol-chips"></div>
    <p class="note">Weight results use the ingredient density you pick below.</p>
  </section>

  <section class="card">
    <h2>Ingredient density</h2>
    <div class="grid" style="margin-top:14px">
      <div class="field">
        <label for="ing">Ingredient</label>
        <select id="ing"></select>
      </div>
      <div class="field">
        <label for="dens">Grams per millilitre</label>
        <input id="dens" type="number" inputmode="decimal" step="any" min="0">
      </div>
    </div>
    <p class="note">1 cup = 240 mL, 1 tbsp = 15 mL, 1 tsp = 5 mL, 1 US cup ≈ 236.6 mL. Water is 1 g/mL. These are close approximations — for baking, weigh your ingredients.</p>
  </section>

  <section class="card">
    <h2>Common conversions</h2>
    <div class="chips" id="presets"></div>
  </section>

  <section>
    <h2 class="sec">Quick reference</h2>
    <table>
      <thead><tr><th>Amount</th><th>Result</th></tr></thead>
      <tbody id="ref"></tbody>
    </table>
    <p class="note">Volume → weight uses the selected ingredient density.</p>
  </section>
</main>

<script>
(function(){
  const $=s=>document.querySelector(s);
  const WEIGHT={g:1,kg:1000,oz:28.3495,lb:453.592};
  const VOLUME={ml:1,l:1000,dl:100,cup:240,tbsp:15,tsp:5,cupus:236.588};
  const WLBL={g:'grams (g)',kg:'kilograms (kg)',oz:'ounces (oz)',lb:'pounds (lb)'};
  const VLBL={ml:'millilitres (mL)',l:'litres (L)',dl:'decilitres (dL)',cup:'cups',tbsp:'tablespoons (tbsp)',tsp:'teaspoons (tsp)',cupus:'US cups'};
  const ING=[{n:'Water',d:1},{n:'All-purpose flour',d:0.53},{n:'Granulated sugar',d:0.85},{n:'Brown sugar (packed)',d:0.7},{n:'Butter',d:0.91},{n:'Milk',d:1.03},{n:'Honey',d:1.42},{n:'Vegetable oil',d:0.92},{n:'Cocoa powder',d:0.46},{n:'Oats (rolled)',d:0.4},{n:'Custom',d:null}];
  const PRESETS=[
    {t:'200 g flour → cups',wt:{v:200,u:'g'},ing:'All-purpose flour'},
    {t:'1 cup sugar → g',wt:{v:1,u:'cup'},ing:'Granulated sugar'},
    {t:'2 dl milk → cups',vol:{v:2,u:'dl'},ing:'Milk'},
    {t:'1 tbsp butter → g',wt:{v:1,u:'tbsp'},ing:'Butter'},
    {t:'100 ml water → tbsp',vol:{v:100,u:'ml'},ing:'Water'},
    {t:'250 g butter → cups',wt:{v:250,u:'g'},ing:'Butter'}
  ];
  const REF=[
    {a:'1 cup',v:{v:1,u:'cup'}},{a:'1 tbsp',v:{v:1,u:'tbsp'}},{a:'1 tsp',v:{v:1,u:'tsp'}},
    {a:'1 dl',v:{v:1,u:'dl'}},{a:'250 ml',v:{v:250,u:'ml'}},{a:'1 kg',w:{v:1,u:'kg'}}
  ];
  const state={wt:{v:'100',u:'g'},vol:{v:'250',u:'ml'},ing:0,dens:1};

  function fmt(x){
    if(!isFinite(x))return '—';
    const a=Math.abs(x);
    if(a===0)return '0';
    if(a<0.0001||a>=1e6)return x.toExponential(2);
    let s=x.toFixed(a>=100?0:a>=10?1:a>=1?2:3);
    if(s.indexOf('.')>=0)s=s.replace(/0+$/,'').replace(/\.$/,'');
    return s;
  }
  function parse(v){const n=parseFloat(String(v).replace(',','.'));return isNaN(n)?0:n;}
  function fill(sel,units,labels,val){
    sel.innerHTML='';
    units.forEach(u=>{const o=document.createElement('option');o.value=u;o.textContent=labels[u];sel.appendChild(o);});
    sel.value=val;
  }
  function renderChips(box,units,labels,dir){
    box.innerHTML='';
    units.forEach(u=>{
      const b=document.createElement('button');b.type='button';b.className='chip';
      b.innerHTML=(dir==='w'?'1 '+labels[u]+' = <b>—</b>':'1 '+labels[u]+' = <b>—</b>');
      b.dataset.unit=u;box.appendChild(b);
    });
  }
  function updateChips(box,units,dir){
    const d=state.dens||1;
    box.querySelectorAll('.chip').forEach(c=>{
      const u=c.dataset.unit;let r;
      if(dir==='w'){const g=WEIGHT[u];r=state.vol.v?g/(VOLUME[u]*d):g/(VOLUME[u]||1);}
      else{const ml=VOLUME[u];r=state.wt.v?(ml*d)/WEIGHT[u]:ml/(WEIGHT[u]||1);}
      c.innerHTML='1 '+labels[u]+' = <b>'+fmt(r)+'</b>';
    });
  }

  function compute(){
    const d=state.dens||1;
    const w=parse(state.wt.v),g=w*WEIGHT[state.wt.u];
    const ml=g/d,cups=ml/VOLUME.cup,tbsp=ml/VOLUME.tbsp;
    $('#wt-result').textContent=fmt(w)+' '+WLBL[state.wt.u];
    $('#wt-hint').textContent=state.wt.v===''?'Enter a weight to see its volume.':
      fmt(cups)+' cups · '+fmt(tbsp)+' tbsp · '+fmt(ml/VOLUME.dl)+' dL';
    updateChips($('#wt-chips'),Object.keys(VOLUME),VLBL,'w');

    const vv=parse(state.vol.v),mlv=vv*VOLUME[state.vol.u];
    const gg=mlv*d,oz=gg/WEIGHT.oz;
    $('#vol-result').textContent=fmt(vv)+' '+VLBL[state.vol.u];
    $('#vol-hint').textContent=state.vol.v===''?'Enter a volume to see its weight.':
      fmt(gg)+' g · '+fmt(gg/1000)+' kg · '+fmt(oz)+' oz';
    updateChips($('#vol-chips'),Object.keys(WEIGHT),WLBL,'v');

    const tb=$('#ref');tb.innerHTML='';
    REF.forEach(r=>{
      const tr=document.createElement('tr'),a=document.createElement('td'),b=document.createElement('td');
      a.textContent=r.a;let html;
      if(r.w){const g=r.w.v*WEIGHT[r.w.u],ml=g/d;html=fmt(g)+' g · '+fmt(ml/VOLUME.cup)+' cups';}
      else{const ml=r.v.v*VOLUME[r.v.u],g=ml*d;html=fmt(g)+' g · '+fmt(g/1000)+' kg';}
      b.innerHTML=html;tr.appendChild(a);tr.appendChild(b);tb.appendChild(tr);
    });
  }

  function applyIngredient(i){
    state.ing=i;const it=ING[i];
    if(it.d!==null){state.dens=it.d;$('#dens').value=it.d;}
    else{$('#dens').value=state.dens;}
    save();compute();
  }
  function applyPreset(p){
    if(p.wt){state.wt.v=String(p.wt.v);state.wt.u=p.wt.u;$('#wt-from').value=p.wt.v;$('#wt-fromu').value=p.wt.u;}
    if(p.vol){state.vol.v=String(p.vol.v);state.vol.u=p.vol.u;$('#vol-from').value=p.vol.v;$('#vol-fromu').value=p.vol.u;}
    if(p.ing){const i=ING.findIndex(x=>x.n===p.ing);if(i>=0){$('#ing').value=i;applyIngredient(i);}}
    save();compute();
  }

  function save(){if(window.alfy&&window.alfy.storage)window.alfy.storage.set('cookconv',state);}
  async function load(){
    try{if(window.alfy&&window.alfy.storage){const s=await window.alfy.storage.get('cookconv');
      if(s){state.wt=s.wt||state.wt;state.vol=s.vol||state.vol;state.ing=s.ing||0;state.dens=s.dens||1;}}}catch(e){}
  }

  function init(){
    fill($('#wt-fromu'),Object.keys(WEIGHT),WLBL,state.wt.u);
    fill($('#vol-fromu'),Object.keys(VOLUME),VLBL,state.vol.u);
    fill($('#ing'),ING.map((x,i)=>i),ING.map(x=>x.n),state.ing);
    $('#wt-from').value=state.wt.v;$('#vol-from').value=state.vol.v;$('#dens').value=state.dens;
    renderChips($('#wt-chips'),Object.keys(VOLUME),VLBL,'w');
    renderChips($('#vol-chips'),Object.keys(WEIGHT),WLBL,'v');

    const pr=$('#presets');
    PRESETS.forEach((p,i)=>{const b=document.createElement('button');b.type='button';b.className='chip';
      b.textContent=p.t;b.addEventListener('click',()=>applyPreset(p));pr.appendChild(b);});

    $('#wt-from').addEventListener('input',e=>{state.wt.v=e.target.value;save();compute();});
    $('#wt-fromu').addEventListener('change',e=>{state.wt.u=e.target.value;save();compute();});
    $('#vol-from').addEventListener('input',e=>{state.vol.v=e.target.value;save();compute();});
    $('#vol-fromu').addEventListener('change',e=>{state.vol.u=e.target.value;save();compute();});
    $('#ing').addEventListener('change',e=>applyIngredient(+e.target.value));
    $('#dens').addEventListener('input',e=>{state.dens=parse(e.target.value);save();compute();});

    compute();
  }

  load().then(init);
})();
</script>
</body>
</html>
